def get_model():
    blob_b64 = ""
    raw = zlib.decompress(base64.b64decode(blob_b64))
    m = torch.jit.load(io.BytesIO(raw), map_location="cpu")
    m.eval()
    return m

#custom search state, same as task 1
@dataclass(frozen=True)
class SearchState:
    agent_pos: Tuple[int, int]
    hp: int
    keys_held: int
    keys_left: Tuple[Tuple[int, int], ...]
    gems_left: Tuple[Tuple[int, int], ...]
    doors_locked: Tuple[Tuple[int, int], ...]
    boxes_pos: Tuple[Tuple[int, int], ...]
    active_powerups: Tuple[Tuple[str, int], ...]
    uncollected_boots: Tuple[Tuple[int, int], ...]
    uncollected_shields: Tuple[Tuple[int, int], ...]
    uncollected_ghosts: Tuple[Tuple[int, int], ...]

class Agent:
    ENTITY_CLASSES = [
        "floor", "wall", "exit", "gem", "key",
        "locked", "lava", "box", "coin",
        "boots", "shield", "ghost", "human", "opened",
    ]

    CLASS_TO_ROLE = {
        "floor":  "floor",
        "wall":   "wall",
        "exit":   "exit",
        "gem":    "gem",
        "key":    "key",
        "locked": "locked_door",
        "lava":   "lava",
        "box":    "box",
        "coin":   "coin",
        "boots":  "boots",
        "shield": "shield",
        "ghost":  "ghost",
        "human":  "agent",
        "opened": "floor", 
    }

    TILE_SIZE = 32

    def __init__(self):
        # planner state (same as Task 1)
        self.actions_to_make = []
        self.has_searched = False
        self.walls: set = set()
        self.lava: set = set()
        self.exit_pos = None
        self.width: int = 0
        self.height: int = 0
        self.bfs_dist_from: dict = {}
        self.coin_positions: set = set()


        self._cnn = get_model()
        self._idx_to_class = {i: c for i, c in enumerate(self.ENTITY_CLASSES)}


    def classify_tiles(self, image_arr: np.ndarray, grid_w: int, grid_h: int) -> dict:
        img_h, img_w = image_arr.shape[:2]
        tile_h = img_h // grid_h
        tile_w = img_w // grid_w #figures out how many pixels each tile occupies

        tiles = []
        positions = []

        for row in range(grid_h):
            for col in range(grid_w):
                tile = image_arr[ # slices out every tile from the full image
                    row * tile_h:(row + 1) * tile_h,
                    col * tile_w:(col + 1) * tile_w,
                ]
                resized = (Image.fromarray(tile.astype(np.uint8))
                           .resize((self.TILE_SIZE, self.TILE_SIZE))) #resizes each image to 32x32 so that we can input it into the CNN
                arr = np.array(resized, dtype=np.float32) / 255.0
                tiles.append(arr.transpose(2, 0, 1))  # (4, 32, 32)
                positions.append((col, row))           # (x, y) convention

        batch = torch.tensor(np.array(tiles), dtype=torch.float32) #runs through the cnn
        with torch.no_grad():
            preds = self._cnn(batch).argmax(dim=1).tolist() #picks the class with the highest logit

        return {pos: self._idx_to_class[p] for pos, p in zip(positions, preds)} #converts the index to class name and returns it back with its coordinates

    def parse(self, observation: ImageObservation) -> dict:
        info = observation["info"]
        W = info["config"]["width"]
        H = info["config"]["height"]
        return self.classify_tiles(observation["image"], W, H)

    def extract_initial_state_from_dict(self, grid_entities: dict, info: dict) -> SearchState: #builds the initial state from the dictionary we created in classify_tiles
        self.width = info["config"]["width"]                                                   #same logic as gridstate initial state but using an imageobservation instead
        self.height = info["config"]["height"]

        agent_pos = None
        gems, coins, doors, boxes, keys = [], [], [], [], []
        boots, shields, ghosts = [], [], []

        starting_hp = info["agent"]["health"]["current_health"]
        keys_held = sum(
            1 for item in info["agent"]["inventory"]
            if "key" in str(item).lower()
        )

        for (x, y), cls in grid_entities.items():
            role = self.CLASS_TO_ROLE.get(cls, "floor")
            if role == "wall":
                self.walls.add((x, y))
            elif role == "lava":
                self.lava.add((x, y))
            elif role == "exit":
                self.exit_pos = (x, y)
            elif role == "agent":
                agent_pos = (x, y)
            elif role == "gem":
                gems.append((x, y))
            elif role == "coin":
                coins.append((x, y))
            elif role == "locked_door":
                doors.append((x, y))
            elif role == "box":
                boxes.append((x, y))
            elif role == "key":
                keys.append((x, y))
            elif role == "boots":
                boots.append((x, y))
            elif role == "shield":
                shields.append((x, y))
            elif role == "ghost":
                ghosts.append((x, y))

        # in case our CNN makes a mistake
        if agent_pos is None:
            agent_pos = (1, 1)
        if self.exit_pos is None:
            for x in range(self.width):
                for y in range(self.height):
                    if (x, y) not in self.walls:
                        self.exit_pos = (x, y)
                        break
                if self.exit_pos:
                    break

        # precompute BFS distances (same as Task 1)
        self.bfs_dist_from = {}
        self.bfs_dist_from[self.exit_pos] = self.precompute_bfs_distances(self.exit_pos)
        for gem_pos in gems:
            self.bfs_dist_from[gem_pos] = self.precompute_bfs_distances(gem_pos)

        self.coin_positions = set(coins)

        return SearchState(
            agent_pos=agent_pos,
            hp=starting_hp,
            keys_held=keys_held,
            keys_left=tuple(keys),
            gems_left=tuple(gems),
            doors_locked=tuple(doors),
            boxes_pos=tuple(sorted(boxes)),
            active_powerups=tuple(),
            uncollected_boots=tuple(boots),
            uncollected_shields=tuple(shields),
            uncollected_ghosts=tuple(ghosts),
        )


    def step(self, state: GridState | ImageObservation) -> Action:
        if not self.has_searched:
            if isinstance(state, dict):  # if we get an imageobservation (Task 2)
                grid_entities = self.parse(state) #returns the dict mapping classnames and coordinates
                initial_state = self.extract_initial_state_from_dict(
                    grid_entities, state["info"]
                ) #build the initial state
            else:  # if we get a grid state (Task 1)
                initial_state = self.extract_initial_state(state)
            self.a_star(initial_state)
            self.has_searched = True

        if self.actions_to_make:
            return self.actions_to_make.pop(0)
        return Action.WAIT

    def info(self) -> dict[str, str]:
        return {"name": "CNN + A* Agent"}

#this portion is same as task 1

    def precompute_bfs_distances(self, target_pos):
        distances = {target_pos: 0}
        queue = deque([(target_pos, 0)])
        while queue:
            (x, y), dist = queue.popleft()
            for nx, ny in [(x, y - 1), (x, y + 1), (x - 1, y), (x + 1, y)]:
                if 0 <= nx < self.width and 0 <= ny < self.height:
                    if (nx, ny) not in self.walls and (nx, ny) not in distances:
                        distances[(nx, ny)] = dist + 1
                        queue.append(((nx, ny), dist + 1))
        return distances

    def extract_initial_state(self, grid: GridState) -> SearchState:
        self.walls = set()
        self.lava = set()
        self.exit_pos = None
        self.width = grid.width
        self.height = grid.height

        agent_pos = None
        gems, coins, doors, boxes, keys = [], [], [], [], []
        boots, shields, ghosts = [], [], []
        starting_hp = None

        for x in range(grid.width):
            for y in range(grid.height):
                pos = (x, y)
                entities = grid.objects_at(pos)
                for e in entities:
                    if isinstance(e, WallEntity):
                        self.walls.add(pos)
                    elif isinstance(e, LavaEntity):
                        self.lava.add(pos)
                    elif isinstance(e, ExitEntity):
                        self.exit_pos = pos
                    elif isinstance(e, AgentEntity):
                        agent_pos = pos
                        starting_hp = e.health.current_health
                    elif isinstance(e, GemEntity):
                        gems.append(pos)
                    elif isinstance(e, CoinEntity):
                        coins.append(pos)
                    elif isinstance(e, LockedDoorEntity):
                        doors.append(pos)
                    elif isinstance(e, BoxEntity):
                        boxes.append(pos)
                    elif isinstance(e, KeyEntity):
                        keys.append(pos)
                    elif isinstance(e, SpeedPowerUpEntity):
                        boots.append(pos)
                    elif isinstance(e, ShieldPowerUpEntity):
                        shields.append(pos)
                    elif isinstance(e, PhasingPowerUpEntity):
                        ghosts.append(pos)

        self.bfs_dist_from = {}
        self.bfs_dist_from[self.exit_pos] = self.precompute_bfs_distances(self.exit_pos)
        for gem_pos in gems:
            self.bfs_dist_from[gem_pos] = self.precompute_bfs_distances(gem_pos)

        self.coin_positions = set(coins)

        return SearchState(
            agent_pos=agent_pos,
            hp=starting_hp,
            keys_held=0,
            keys_left=tuple(keys),
            gems_left=tuple(gems),
            doors_locked=tuple(doors),
            boxes_pos=tuple(sorted(boxes)),
            active_powerups=tuple(),
            uncollected_boots=tuple(boots),
            uncollected_shields=tuple(shields),
            uncollected_ghosts=tuple(ghosts),
        )

    def get_successors(self, state: SearchState):
        x, y = state.agent_pos

        ticked_powerups = tuple(
            (name, dur) if name == "ShieldPowerUpEntity" else (name, dur - 1)
            for name, dur in state.active_powerups
            if name == "ShieldPowerUpEntity" or dur > 1
        )

        has_speed = any(n == "SpeedPowerUpEntity" for n, _ in state.active_powerups)
        has_ghost = any(n == "PhasingPowerUpEntity" for n, _ in state.active_powerups)
        doors_set = set(state.doors_locked)
        boxes_set = set(state.boxes_pos)

        successors = []
        successors.extend(self.pickup_successors(state, x, y, ticked_powerups))
        successors.extend(self.movement_successors(
            state, x, y, ticked_powerups, has_speed, has_ghost, doors_set, boxes_set))
        successors.extend(self.use_key_successors(state, x, y, ticked_powerups, doors_set))
        return successors

    def pickup_successors(self, state, x, y, ticked):
        if (x, y) in state.keys_left:
            return [(replace(state,
                keys_held=state.keys_held + 1,
                keys_left=tuple(k for k in state.keys_left if k != (x, y)),
                active_powerups=ticked), Action.PICK_UP)]

        if (x, y) in state.gems_left:
            return [(replace(state,
                gems_left=tuple(g for g in state.gems_left if g != (x, y)),
                active_powerups=ticked), Action.PICK_UP)]

        if (x, y) in state.uncollected_boots:
            return [(replace(state,
                uncollected_boots=tuple(b for b in state.uncollected_boots if b != (x, y)),
                active_powerups=tuple(sorted(ticked + (("SpeedPowerUpEntity", 5),)))),
                Action.PICK_UP)]

        if (x, y) in state.uncollected_shields:
            return [(replace(state,
                uncollected_shields=tuple(s for s in state.uncollected_shields if s != (x, y)),
                active_powerups=tuple(sorted(ticked + (("ShieldPowerUpEntity", 5),)))),
                Action.PICK_UP)]

        if (x, y) in state.uncollected_ghosts:
            return [(replace(state,
                uncollected_ghosts=tuple(g for g in state.uncollected_ghosts if g != (x, y)),
                active_powerups=tuple(sorted(ticked + (("PhasingPowerUpEntity", 5),)))),
                Action.PICK_UP)]

        return []

    def movement_successors(self, state, x, y, ticked, has_speed, has_ghost, doors_set, boxes_set):
        results = []
        directions = {
            Action.UP: (0, -1), Action.DOWN: (0, 1),
            Action.LEFT: (-1, 0), Action.RIGHT: (1, 0),
        }

        for action, (dx, dy) in directions.items():
            max_steps = 2 if has_speed else 1
            final_pos = (x, y)
            cur_boxes = list(state.boxes_pos)
            cur_box_set = set(cur_boxes)
            path = []

            for step in range(1, max_steps + 1):
                nx, ny = x + dx * step, y + dy * step

                if not (0 <= nx < self.width and 0 <= ny < self.height):
                    break

                if has_ghost:
                    final_pos = (nx, ny)
                    path.append((nx, ny))
                    continue

                if (nx, ny) in self.walls or (nx, ny) in doors_set:
                    break

                if (nx, ny) in cur_box_set:
                    bx, by = nx + dx, ny + dy
                    if not (0 <= bx < self.width and 0 <= by < self.height):
                        break
                    if (bx, by) in self.walls or (bx, by) in doors_set or (bx, by) in cur_box_set:
                        break
                    cur_boxes = [(bx, by) if b == (nx, ny) else b for b in cur_boxes]
                    cur_box_set = cur_box_set - {(nx, ny)} | {(bx, by)}

                final_pos = (nx, ny)
                path.append((nx, ny))

            if final_pos == (x, y):
                continue

            next_hp = state.hp
            final_powerups = list(ticked)
            if not has_ghost:
                for pos in path:
                    if pos in self.lava:
                        shield_found = False
                        for i, (name, uses) in enumerate(final_powerups):
                            if name == "ShieldPowerUpEntity":
                                shield_found = True
                                if uses > 1:
                                    final_powerups[i] = (name, uses - 1)
                                else:
                                    final_powerups.pop(i)
                                break
                        if not shield_found:
                            next_hp -= 2
                        if next_hp <= 0:
                            break

            if next_hp <= 0:
                continue

            next_state = replace(state,
                agent_pos=final_pos,
                hp=next_hp,
                boxes_pos=tuple(sorted(cur_boxes)),
                active_powerups=tuple(sorted(final_powerups)))
            results.append((next_state, action))

        return results

    def use_key_successors(self, state, x, y, ticked, doors_set):
        if state.keys_held <= 0:
            return []

        to_unlock = []
        keys_available = state.keys_held
        for pos in [(x, y), (x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)]:
            if pos in doors_set and keys_available > 0:
                to_unlock.append(pos)
                keys_available -= 1

        if not to_unlock:
            return []

        unlock_set = set(to_unlock)
        return [(replace(state,
            keys_held=state.keys_held - len(to_unlock),
            doors_locked=tuple(d for d in state.doors_locked if d not in unlock_set),
            active_powerups=ticked), Action.USE_KEY)]

    def heuristic(self, state: SearchState) -> int:
        if not state.gems_left and state.agent_pos == self.exit_pos:
            return 0

        def get_dist(p1, p2):
            if p1 == p2:
                return 0
            if p2 in self.bfs_dist_from and p1 in self.bfs_dist_from[p2]:
                return self.bfs_dist_from[p2][p1]
            if p1 in self.bfs_dist_from and p2 in self.bfs_dist_from[p1]:
                return self.bfs_dist_from[p1][p2]
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        if state.gems_left:
            dist_agent_to_gem = min(get_dist(state.agent_pos, g) for g in state.gems_left)
            dist_gem_to_exit = min(get_dist(g, self.exit_pos) for g in state.gems_left)
            total_dist = dist_agent_to_gem + dist_gem_to_exit
        else:
            total_dist = get_dist(state.agent_pos, self.exit_pos)

        return math.ceil(total_dist / 2) * 3

    def a_star(self, initial_state: SearchState):
        counter = itertools.count()
        frontier = []
        heapq.heappush(frontier, (self.heuristic(initial_state), next(counter), initial_state))
        gn = {initial_state: 0}
        came_from = {}
        visited = {}

        while frontier:
            f, _, current_state = heapq.heappop(frontier)

            if current_state in visited and visited[current_state] <= gn[current_state]:
                continue
            visited[current_state] = gn[current_state]

            if len(current_state.gems_left) == 0 and current_state.agent_pos == self.exit_pos:
                self.actions_to_make = self.reconstruct_path(came_from, current_state)
                return

            for next_state, action in self.get_successors(current_state):
                action_cost = self.calculate_action_cost(current_state, next_state, action)
                new_gn = gn[current_state] + action_cost
                if new_gn < gn.get(next_state, float("inf")):
                    came_from[next_state] = current_state, action
                    gn[next_state] = new_gn
                    fn = new_gn + self.heuristic(next_state)
                    heapq.heappush(frontier, (fn, next(counter), next_state))

        self.actions_to_make = []

    def reconstruct_path(self, came_from, current_state):
        pairs = []
        while current_state in came_from:
            prev_state, action = came_from[current_state]
            pairs.append((prev_state, action, current_state))
            current_state = prev_state
        pairs.reverse()

        final_path = []
        remaining_coins = set(self.coin_positions)
        for prev_state, action, next_state in pairs:
            final_path.append(action)
            if action in (Action.UP, Action.DOWN, Action.LEFT, Action.RIGHT):
                landed = next_state.agent_pos
                if landed in remaining_coins:
                    final_path.append(Action.PICK_UP)
                    remaining_coins.discard(landed)

        return final_path

    def calculate_action_cost(self, current_state: SearchState, next_state: SearchState,
                              action: Action) -> int:
        return 3
